sealed class PpException: kotlin.Exception() {
    
    /**
     * Not a PDF, or broken beyond repair.
     */
    class Damaged(
        
        val `why`: kotlin.String
        ) : PpException() {
        override val message
            get() = "why=${ `why` }"
    }
    
    /**
     * The file needs its password, or the one given is wrong.
     */
    class Password(
        ) : PpException() {
        override val message
            get() = ""
    }
    
    /**
     * Too many pages or too much data to handle safely.
     */
    class TooBig(
        
        val `why`: kotlin.String
        ) : PpException() {
        override val message
            get() = "why=${ `why` }"
    }
    
    /**
     * A page that isn't there (`file` counts from 0, `page` from 1).
     */
    class NoSuchPage(
        
        val `file`: kotlin.UInt, 
        
        val `page`: kotlin.UInt
        ) : PpException() {
        override val message
            get() = "file=${ `file` }, page=${ `page` }"
    }
    
    /**
     * Nothing to make: no pages or no pictures.
     */
    class Empty(
        ) : PpException() {
        override val message
            get() = ""
    }
    
    /**
     * [`load_engine`] has not run (or failed): reading needs PDFium.
     */
    class NoEngine(
        
        val `why`: kotlin.String
        ) : PpException() {
        override val message
            get() = "why=${ `why` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<PpException> {
        override fun lift(error_buf: RustBuffer.ByValue): PpException = FfiConverterTypePpError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypePpError : FfiConverterRustBuffer<PpException> {
    override fun read(buf: ByteBuffer): PpException {
        

        return when(buf.getInt()) {
            1 -> PpException.Damaged(
                FfiConverterString.read(buf),
                )
            2 -> PpException.Password()
            3 -> PpException.TooBig(
                FfiConverterString.read(buf),
                )
            4 -> PpException.NoSuchPage(
                FfiConverterUInt.read(buf),
                FfiConverterUInt.read(buf),
                )
            5 -> PpException.Empty()
            6 -> PpException.NoEngine(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: PpException): ULong {
        return when(value) {
            is PpException.Damaged -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`why`)
            )
            is PpException.Password -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is PpException.TooBig -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`why`)
            )
            is PpException.NoSuchPage -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUInt.allocationSize(value.`file`)
                + FfiConverterUInt.allocationSize(value.`page`)
            )
            is PpException.Empty -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is PpException.NoEngine -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`why`)
            )
        }
    }

    override fun write(value: PpException, buf: ByteBuffer) {
        when(value) {
            is PpException.Damaged -> {
                buf.putInt(1)
                FfiConverterString.write(value.`why`, buf)
                Unit
            }
            is PpException.Password -> {
                buf.putInt(2)
                Unit
            }
            is PpException.TooBig -> {
                buf.putInt(3)
                FfiConverterString.write(value.`why`, buf)
                Unit
            }
            is PpException.NoSuchPage -> {
                buf.putInt(4)
                FfiConverterUInt.write(value.`file`, buf)
                FfiConverterUInt.write(value.`page`, buf)
                Unit
            }
            is PpException.Empty -> {
                buf.putInt(5)
                Unit
            }
            is PpException.NoEngine -> {
                buf.putInt(6)
                FfiConverterString.write(value.`why`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



